def solve(record):
    """
    Aggregate signed quantities per item from record['record_1'].

    The item codes may have inconsistent capitalization because they come from
    a keyboard with a stuck caps lock, so we normalize them to lower case.
    The returned dictionary maps each normalized code to its net quantity,
    which represents the folded inventory total.
