from collections import deque

def solve(record):
    x = record.get('record_0')
    if not isinstance(x, (list, tuple)) or len(x) != 3:
        return None
    edges, source, target = x

    # Build adjacency list for the directed graph
    adj = {}
    for edge in edges:
        if isinstance(edge, (list, tuple)) and len(edge) == 2:
            a, b = edge
            adj.setdefault(a, []).append(b)

    # A stationary traveler already arrived: zero distance if source equals target
    if source == target:
        return 0

    # Breadth‑first search to find the shortest directed path
    visited = {source}
    queue = deque([(source, 0)])

    while queue:
        node, dist = queue.popleft()
        for neighbor in adj.get(node, []):
            if neighbor == target:
                return dist + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    # No route found
    return None

