def solve(record):
    x = record.get('record_2')
    if not isinstance(x, list) or len(x) != 3:
        return None
    edges, source, target = x

    # Build adjacency list for the directed graph
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)

    # If source and target are the same, we need a directed cycle of length > 0
    if source == target:
        visited = {source}
        q = deque()
        # start from all outgoing edges of the source
        for nb in adj.get(source, []):
            if nb == source:               # self-loop
                return 1
