    queue = deque([source])
    distance = {source: 0}
    while queue:
        node = queue.popleft()
        for nxt in adj.get(node, []):
            if nxt not in distance:
                distance[nxt] = distance[node] + 1
                if nxt == target:
                    return distance[nxt]
                queue.append(nxt)
    return -1
